// Regenerated by `pnpm gen:api` against the live backend's /openapi.json.
// This checked-in version is a minimal fallback so the project type-checks
// before the backend has been run once; CI regenerates and diffs it.
export interface paths {
  "/healthz": {
    get: {
      responses: {
        200: { content: { "application/json": { status: string } } };
      };
    };
  };
  "/api/settings": {
    get: {
      responses: {
        200: {
          content: {
            "application/json": { verbosity: string; pace: string };
          };
        };
      };
    };
    put: {
      requestBody: {
        content: { "application/json": { verbosity?: string; pace?: string } };
      };
      responses: {
        200: {
          content: {
            "application/json": { verbosity: string; pace: string };
          };
        };
      };
    };
  };
}
